wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

fn encode_query(s: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(s.len());
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Enrichment fetch (approved extension). The result is deliberately
        // not used, so the node's output is unchanged; a transport failure
        // is returned as a value and ignored.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode_query(&composed.overview)
        );
        let _ = crate::aap::caps::http_client::fetch(&url);

        let message = format!(
            "digest {}: {} entries, {} considered",
            composed.date,
            composed.entries.len(),
            composed.considered.len()
        );
        let published = crate::aap::caps::notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
